#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/aff3ct/turbo_encoder.h>

void bind_turbo_encoder(py::module& m)
{
    using turbo_encoder = ::gr::aff3ct::turbo_encoder;

    py::class_<turbo_encoder, gr::fec::generic_encoder, std::shared_ptr<turbo_encoder>>(
        m,
        "turbo_encoder",
        py::multiple_inheritance(), // generic_encoder is a virtual base: pointers must be adjusted
        "AFF3CT turbo encoder (LTE constituent codes, any K and N).")
        .def_static("make",
                    &turbo_encoder::make,
                    py::arg("K"),
                    py::arg("N"),
                    py::arg("interleaver") = "AUTO",
                    py::arg("seed") = 0,
                    py::arg("aff3ct_args") = "")
        .def("interleaver", &turbo_encoder::interleaver);
}
